const std = @import("std");

const MODULUS: u64 = 33_554_393;
const MULTIPLIER: u64 = 252_533;

fn modPow(base: u64, exponent: u64, modulus: u64) u64 {
    var result: u64 = 1;
    var b = base % modulus;
    var e = exponent;

    while (e > 0) {
        if ((e & 1) != 0) result = (result * b) % modulus;
        b = (b * b) % modulus;
        e >>= 1;
    }
    return result;
}

pub fn main() !void {
    const allocator = std.heap.page_allocator;
    const input = try std.fs.cwd().readFileAlloc(allocator, "input.txt", 1024 * 1024);
    defer allocator.free(input);

    var coords: [2]u64 = undefined;
    var found: usize = 0;
    var i: usize = 0;

    while (i < input.len) {
        if (input[i] >= '0' and input[i] <= '9') {
            const start = i;
            while (i < input.len and input[i] >= '0' and input[i] <= '9') : (i += 1) {}

            if (found < coords.len) {
                coords[found] = try std.fmt.parseInt(u64, input[start..i], 10);
                found += 1;
            }
        } else {
            i += 1;
        }
    }

    if (found != 2) return error.ExpectedRowAndColumn;

    const row = coords[0];
    const col = coords[1];
    const diagonal = row + col - 1;

    // Zero-based number of steps from the first code to this position.
    const steps = diagonal * (diagonal - 1) / 2 + diagonal - row;

    const code = (20_151_125 * modPow(MULTIPLIER, steps, MODULUS)) % MODULUS;

    const stdout = std.io.getStdOut().writer();
    try stdout.print("{d}\n", .{code});
}
```

